function DENSITY_THRESHOLD_CHECK(n, m):
    rho <- (n = 0) ? 0 : m / n        # exact rational
    return (rho, rho < 1, rho < 3/2)

function IS_FOREST_ACYCLIC(n, edges):
    parent[i] <- i for i in 0..n-1
    for (a,b) in edges:
        if FIND(a) = FIND(b): return False   # cycle => K3 minor
        UNION(a,b)
    return True
